     1→import * as vscode from 'vscode';
     2→
     3→/**
     4→ * Message types between extension and WebView
     5→ */
     6→interface AudioDataMessage {
     7→    type: 'audio';
     8→    data: number[]; // Float32Array serialized as array
     9→    sampleRate: number;
    10→}
    11→
    12→interface ReadyMessage {
    13→    type: 'ready';
    14→}
    15→
    16→interface ErrorMessage {
    17→    type: 'error';
    18→    message: string;
    19→}
    20→
    21→type WebViewMessage = AudioDataMessage | ReadyMessage | ErrorMessage;
    22→
    23→/**
    24→ * Audio capture WebView provider
    25→ * Implements audio capture using Web Audio API in a WebView
    26→ * Per ADR-003: Uses Web Audio API for cross-platform audio capture
    27→ */
    28→export class VoiceInputViewProvider implements vscode.WebviewViewProvider {
    29→    public static readonly viewType = 'vtthought.voiceInputView';
    30→
    31→    private _view?: vscode.WebviewView;
    32→
    33→    // Callbacks for audio data events
    34→    private onAudioDataCallbacks: ((data: Float32Array, sampleRate: number) => void)[] = [];
    35→    private onErrorCallbacks: ((error: string) => void)[] = [];
    36→
    37→    constructor(private readonly _extensionUri: vscode.Uri) {}
    38→
    39→    /**
    40→     * Register callback for audio data
    41→     */
    42→    public onAudioData(callback: (data: Float32Array, sampleRate: number) => void): void {
    43→        this.onAudioDataCallbacks.push(callback);
    44→    }
    45→
    46→    /**
    47→     * Register callback for errors
    48→     */
    49→    public onError(callback: (error: string) => void): void {
    50→        this.onErrorCallbacks.push(callback);
    51→    }
    52→
    53→    /**
    54→     * Resolve the WebView view
    55→     */
    56→    public resolveWebviewView(
    57→        webviewView: vscode.WebviewView,
    58→        context: vscode.WebviewViewResolveContext,
    59→        _token: vscode.CancellationToken
    60→    ): void {
    61→        this._view = webviewView;
    62→
    63→        webviewView.webview.options = {
    64→            enableScripts: true,
    65→            localResourceRoots: [this._extensionUri]
    66→        };
    67→
    68→        webviewView.webview.html = this._getHtmlForWebview(webviewView.webview);
    69→
    70→        // Handle messages from WebView
    71→        webviewView.webview.onDidReceiveMessage(
    72→            (message: WebViewMessage) => {
    73→                switch (message.type) {
    74→                    case 'audio':
    75→                        // Convert array back to Float32Array
    76→                        const audioData = new Float32Array(message.data);
    77→                        this.onAudioDataCallbacks.forEach(cb => cb(audioData, message.sampleRate));
    78→                        break;
    79→                    case 'ready':
    80→                        // WebView is ready to accept commands
    81→                        break;
    82→                    case 'error':
    83→                        this.onErrorCallbacks.forEach(cb => cb(message.message));
    84→                        break;
    85→                }
    86→            },
    87→            undefined,
    88→            undefined
    89→        );
    90→    }
    91→
    92→    /**
    93→     * Send start recording command to WebView
    94→     */
    95→    public startRecording(): void {
    96→        if (this._view) {
    97→            this._view.webview.postMessage({ command: 'start' });
    98→        }
    99→    }
   100→
   101→    /**
   102→     * Send stop recording command to WebView
   103→     */
   104→    public stopRecording(): void {
   105→        if (this._view) {
   106→            this._view.webview.postMessage({ command: 'stop' });
   107→        }
   108→    }
   109→
   110→    /**
   111→     * Get the WebView HTML
   112→     */
   113→    private _getHtmlForWebview(webview: vscode.Webview): string {
   114→        return `<!DOCTYPE html>
   115→<html lang="en">
   116→<head>
   117→    <meta charset="UTF-8">
   118→    <meta name="viewport" content="width=device-width, initial-scale=1.0">
   119→    <meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline' 'unsafe-eval'; style-src 'unsafe-inline';">
   120→    <title>VTThought Voice Input</title>
   121→    <style>
   122→        body {
   123→            padding: 10px;
   124→            font-family: var(--vscode-font-family);
   125→            font-size: var(--vscode-font-size);
   126→            color: var(--vscode-foreground);
   127→            background-color: var(--vscode-editor-background);
   128→        }
   129→        .container {
   130→            display: flex;
   131→            flex-direction: column;
   132→            gap: 10px;
   133→        }
   134→        .status {
   135→            padding: 8px;
   136→            border-radius: 4px;
   137→            font-size: 12px;
   138→        }
   139→        .status.idle {
   140→            background-color: var(--vscode-editorInfo-background);
   141→            color: var(--vscode-editorInfo-foreground);
   142→        }
   143→        .status.recording {
   144→            background-color: var(--vscode-errorBackground);
   145→            color: var(--vscode-errorForeground);
   146→            animation: pulse 1.5s infinite;
   147→        }
   148→        .status.error {
   149→            background-color: var(--vscode-editorWarningBackground);
   150→            color: var(--vscode-editorWarning-foreground);
   151→        }
   152→        @keyframes pulse {
   153→            0%, 100% { opacity: 1; }
   154→            50% { opacity: 0.7; }
   155→        }
   156→        .level-meter {
   157→            height: 8px;
   158→            background-color: var(--vscode-progressBar-background);
   159→            border-radius: 4px;
   160→            overflow: hidden;
   161→        }
   162→        .level-meter-fill {
   163→            height: 100%;
   164→            background-color: var(--vscode-progressBar-foreground);
   165→            width: 0%;
   166→            transition: width 0.05s ease-out;
   167→        }
   168→        .info {
   169→            font-size: 11px;
   170→            color: var(--vscode-descriptionForeground);
   171→        }
   172→    </style>
   173→</head>
   174→<body>
   175→    <div class="container">
   176→        <div id="status" class="status idle">
   177→            Ready - Press Ctrl+Alt+V to record
   178→        </div>
   179→        <div class="level-meter">
   180→            <div id="levelMeter" class="level-meter-fill"></div>
   181→        </div>
   182→        <div class="info">
   183→            Sample Rate: <span id="sampleRate">-</span> Hz<br>
   184→            Chunk Size: <span id="chunkSize">-</span> samples
   185→        </div>
   186→    </div>
   187→
   188→    <script>
   189→        (function() {
   190→            const vscode = acquireVsCodeApi();
   191→
   192→            // Audio context and nodes
   193→            let audioContext: AudioContext | null = null;
   194→            let mediaStream: MediaStream | null = null;
   195→            let source: MediaStreamAudioSourceNode | null = null;
   196→            let processorNode: AudioWorkletNode | null = null;
   197→            let scriptProcessor: ScriptProcessorNode | null = null;
   198→
   199→            // Configuration
   200→            const TARGET_SAMPLE_RATE = 16000; // Whisper optimal
   201→            const BUFFER_SIZE = 4096; // ~256ms at 16kHz
   202→
   203→            // DOM elements
   204→            const statusEl = document.getElementById('status');
   205→            const levelMeterEl = document.getElementById('levelMeter');
   206→            const sampleRateEl = document.getElementById('sampleRate');
   207→            const chunkSizeEl = document.getElementById('chunkSize');
   208→
   209→            // Update status display
   210→            function setStatus(state: string, message: string) {
   211→                statusEl.className = 'status ' + state;
   212→                statusEl.textContent = message;
   213→            }
   214→
   215→            // Update level meter
   216→            function updateLevelMeter(rms: number) {
   217→                // Convert RMS to percentage (0-100)
   218→                // Typical speech RMS is around 0.01-0.1
   219→                const level = Math.min(100, Math.max(0, rms * 1000));
   220→                levelMeterEl.style.width = level + '%';
   221→            }
   222→
   223→            // Calculate RMS of audio samples
   224→            function calculateRMS(samples: Float32Array): number {
   225→                let sum = 0;
   226→                for (let i = 0; i < samples.length; i++) {
   227→                    sum += samples[i] * samples[i];
   228→                }
   229→                return Math.sqrt(sum / samples.length);
   230→            }
   231→
   232→            // Send audio data to extension
   233→            function sendAudioData(samples: Float32Array) {
   234→                // Update level meter
   235→                const rms = calculateRMS(samples);
   236→                updateLevelMeter(rms);
   237→
   238→                // Send to extension
   239→                vscode.postMessage({
   240→                    type: 'audio',
   241→                    data: Array.from(samples),
   242→                    sampleRate: TARGET_SAMPLE_RATE
   243→                });
   244→            }
   245→
   246→            // AudioWorklet processor code (inline version)
   247→            const workletCode = \`
   248→                class AudioProcessor extends AudioWorkletProcessor {
   249→                    constructor() {
   250→                        super();
   251→                        this.buffer = [];
   252→                        this.bufferSize = \${BUFFER_SIZE};
   253→                    }
   254→
   255→                    process(inputs: Float32Array[][], outputs: Float32Array[][], parameters: Record<string, Float32Array>): boolean {
   256→                        const input = inputs[0];
   257→                        if (input.length > 0) {
   258→                            const samples = input[0];
   259→                            // Convert stereo to mono if needed
   260→                            for (let i = 0; i < samples.length; i++) {
   261→                                this.buffer.push(samples[i]);
   262→                            }
   263→
   264→                            if (this.buffer.length >= this.bufferSize) {
   265→                                const chunk = new Float32Array(this.buffer.splice(0, this.bufferSize));
   266→                                this.port.postMessage(chunk);
   267→                            }
   268→                        }
   269→                        return true;
   270→                    }
   271→                }
   272→
   273→                registerProcessor('audio-processor', AudioProcessor);
   274→            \`;
   275→
   276→            // Start audio capture
   277→            async function startCapture() {
   278→                try {
   279→                    setStatus('idle', 'Requesting microphone access...');
   280→
   281→                    // Get user media with optimal constraints
   282→                    mediaStream = await navigator.mediaDevices.getUserMedia({
   283→                        audio: {
   284→                            sampleRate: TARGET_SAMPLE_RATE,
   285→                            channelCount: 1,
   286→                            echoCancellation: true,
   287→                            noiseSuppression: true,
   288→                            autoGainControl: true
   289→                        }
   290→                    });
   291→
   292→                    // Create audio context
   293→                    audioContext = new AudioContext({ sampleRate: TARGET_SAMPLE_RATE });
   294→
   295→                    // Update info display
   296→                    sampleRateEl.textContent = audioContext.sampleRate.toString();
   297→                    chunkSizeEl.textContent = BUFFER_SIZE.toString();
   298→
   299→                    // Create source
   300→                    source = audioContext.createMediaStreamSource(mediaStream);
   301→
   302→                    // Try to use AudioWorklet (preferred)
   303→                    try {
   304→                        const blob = new Blob([workletCode], { type: 'application/javascript' });
   305→                        const workletUrl = URL.createObjectURL(blob);
   306→                        await audioContext.audioWorklet.addModule(workletUrl);
   307→                        URL.revokeObjectURL(workletUrl);
   308→
   309→                        processorNode = new AudioWorkletNode(audioContext, 'audio-processor');
   310→                        processorNode.port.onmessage = (e: MessageEvent) => {
   311→                            sendAudioData(e.data as Float32Array);
   312→                        };
   313→
   314→                        source.connect(processorNode);
   315→                        setStatus('recording', 'Recording... (Release key to stop)');
   316→                    } catch (workletError) {
   317→                        // Fallback to ScriptProcessorNode
   318→                        console.warn('AudioWorklet failed, using ScriptProcessorNode fallback:', workletError);
   319→
   320→                        let buffer: number[] = [];
   321→
   322→                        scriptProcessor = audioContext.createScriptProcessor(
   323→                            BUFFER_SIZE,
   324→                            1,
   325→                            1
   326→                        );
   327→
   328→                        scriptProcessor.onaudioprocess = (e: AudioProcessingEvent) => {
   329→                            const samples = e.inputBuffer.getChannelData(0);
   330→                            sendAudioData(new Float32Array(samples));
   331→                        };
   332→
   333→                        source.connect(scriptProcessor);
   334→                        scriptProcessor.connect(audioContext.destination);
   335→                        setStatus('recording', 'Recording... (Release key to stop)');
   336→                    }
   337→
   338→                    vscode.postMessage({ type: 'ready' });
   339→
   340→                } catch (error) {
   341→                    console.error('Failed to start audio capture:', error);
   342→                    let errorMsg = 'Failed to start recording';
   343→                    if (error instanceof Error) {
   344→                        if (error.name === 'NotAllowedError') {
   345→                            errorMsg = 'Microphone permission denied. Please allow microphone access in your browser settings.';
   346→                        } else if (error.name === 'NotFoundError') {
   347→                            errorMsg = 'No microphone found. Please connect a microphone.';
   348→                        } else {
   349→                            errorMsg = error.message;
   350→                        }
   351→                    }
   352→                    setStatus('error', errorMsg);
   353→                    vscode.postMessage({ type: 'error', message: errorMsg });
   354→                }
   355→            }
   356→
   357→            // Stop audio capture
   358→            function stopCapture() {
   359→                setStatus('idle', 'Stopping...');
   360→
   361→                // Disconnect and cleanup
   362→                if (processorNode) {
   363→                    processorNode.disconnect();
   364→                    processorNode = null;
   365→                }
   366→
   367→                if (scriptProcessor) {
   368→                    scriptProcessor.disconnect();
   369→                    scriptProcessor = null;
   370→                }
   371→
   372→                if (source) {
   373→                    source.disconnect();
   374→                    source = null;
   375→                }
   376→
   377→                if (mediaStream) {
   378→                    mediaStream.getTracks().forEach(track => track.stop());
   379→                    mediaStream = null;
   380→                }
   381→
   382→                if (audioContext) {
   383→                    audioContext.close();
   384→                    audioContext = null;
   385→                }
   386→
   387→                levelMeterEl.style.width = '0%';
   388→                setStatus('idle', 'Ready - Press Ctrl+Alt+V to record');
   389→            }
   390→
   391→            // Listen for messages from extension
   392→            window.addEventListener('message', (event: MessageEvent) => {
   393→                const command = event.data.command;
   394→                if (command === 'start') {
   395→                    startCapture();
   396→                } else if (command === 'stop') {
   397→                    stopCapture();
   398→                }
   399→            });
   400→
   401→            // Auto-start on load if extension signals it
   402→            vscode.postMessage({ type: 'ready' });
   403→        })();
   404→    </script>
   405→</body>
   406→</html>`;
   407→    }
   408→}
