   692→    private updateStatusDisplay(): void {
   693→        // Recording status
   694→        if (this.state.isRecording) {
   695→            this.statusBarItem.text = '$record VTThought: Recording';
   696→            this.statusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
   697→            this.statusBarItem.tooltip = 'Click to stop recording';
   698→        } else {
   699→            this.statusBarItem.text = '$circle-large-outline VTThought: Idle';
   700→            this.statusBarItem.backgroundColor = undefined;
   701→            this.statusBarItem.tooltip = 'Click to start recording (Ctrl+Alt+V)';
