   223→    private commands: VoiceCommand[];
   224→    private detectionMode: 'trailing' | 'anywhere';
   225→
   226→    constructor(commands?: VoiceCommand[], detectionMode: 'trailing' | 'anywhere' = 'trailing') {
   227→        this.commands = commands ?? VOICE_COMMANDS;
   228→        this.detectionMode = detectionMode;
   229→    }
