   231→    /**
   232→     * Create a parser with custom commands from VS Code settings
   233→     */
   234→    static withSettings(): CommandParser {
   235→        const config = vscode.workspace.getConfiguration('vtthought');
   236→
   237→        // Get disabled commands
   238→        const disabledActions = new Set(
   239→            config.get<string[]>('disabledCommands', [])
   240→        );
   241→
   242→        // Start with built-in commands
   243→        let commands = VOICE_COMMANDS.filter(cmd => !disabledActions.has(cmd.action));
   244→
   245→        // Add custom commands from settings
   246→        const customCommands = config.get<any[]>('customCommands', []);
   247→        for (const custom of customCommands) {
   248→            if (custom.trigger && custom.action) {
   249→                commands.push({
   250→                    trigger: custom.trigger,
   251→                    action: custom.action,
   252→                    params: custom.params ? () => custom.params : undefined,
   253→                    terminal: custom.terminal || false
   254→                });
   255→            }
   256→        }
   257→
   258→        const detectionMode = config.get<'trailing' | 'anywhere'>('commandDetection', 'trailing');
   259→
   260→        return new CommandParser(commands, detectionMode);
   261→    }
   262→
   263→    parse(transcription: string): ParsedTranscription {
   264→        let text = transcription;
   265→        const foundCommands: Command[] = [];
   266→
   267→        // Check for commands based on detection mode
   268→        for (const cmd of this.commands) {
   269→            for (const trigger of cmd.trigger) {
   270→                const regex = this.detectionMode === 'trailing'
   271→                    ? new RegExp(`\\s*${this.escapeRegex(trigger)}\\s*$`, 'i')
   272→                    : new RegExp(`\\b${this.escapeRegex(trigger)}\\b`, 'gi');
   273→
   274→                let match: RegExpExecArray | null;
   275→                while ((match = regex.exec(text)) !== null) {
   276→                    // Remove command from text
   277→                    text = text.replace(regex, '').trim();
   278→
   279→                    foundCommands.push({
   280→                        action: cmd.action,
   281→                        params: cmd.params?.(transcription) ?? undefined,
   282→                        terminal: cmd.terminal
   283→                    });
   284→
   285→                    if (this.detectionMode === 'trailing') {
   286→                        break; // Only check first match for trailing mode
   287→                    }
   288→                }
   289→            }
   290→        }
   291→
   292→        return {
   293→            text,
   294→            commands: foundCommands.reverse(),  // Execute in order spoken
   295→            hasTrailingCommand: foundCommands.length > 0
   296→        };
   297→    }
   298→
   299→    private escapeRegex(str: string): string {
   300→        return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
   301→    }
   302→
   303→    /**
   304→     * Get all available commands for display
   305→     */
   306→    getCommandList(): VoiceCommand[] {
   307→        return this.commands;
   308→    }
   309→}
   310→
   311→/**
   312→ * Executes parsed voice commands.
   313→ */
   314→export class CommandExecutor {
   315→    async execute(command: Command): Promise<void> {
   316→        if (command.terminal) {
   317→            await this.executeTerminalCommand(command);
   318→        } else {
   319→            await vscode.commands.executeCommand(
   320→                command.action,
   321→                command.params
   322→            );
   323→        }
   324→    }
   325→
   326→    private async executeTerminalCommand(command: Command): Promise<void> {
   327→        const terminal = vscode.window.activeTerminal;
   328→        if (!terminal) {
   329→            vscode.window.showWarningMessage('No active terminal for command');
   330→            return;
   331→        }
   332→
   333→        switch (command.action) {
   334→            case 'terminal.send-enter':
   335→                terminal.sendText('', true);  // Empty string with execute=true
   336→                break;
   337→            case 'terminal.send-ctrl-c':
   338→                terminal.sendText('\x03', false);
   339→                break;
   340→            case 'terminal.clear-line':
   341→                terminal.sendText('\u0015', false);  // Ctrl+U
   342→                break;
   343→            default:
   344→                vscode.window.showWarningMessage(`Unknown terminal command: ${command.action}`);
   345→        }
   346→    }
   347→}
   348→
   349→/**
   350→ * Disambiguation for homophones (similar-sounding words).
   351→ * From ADR-008.
   352→ */
   353→const HOMOPHONES: Record<string, string[]> = {
   354→    'enter': ['inter', 'inner'],
   355→    'send': ['sent', 'scent'],
   356→    'delete': ['the lead', 'dilute'],
   357→    'undo': ['un do', 'and do'],
   358→    'redo': ['re do', 're-do'],
   359→    'copy': ['copy that', 'copi'],
   360→    'cut': ['cut that'],
   361→    'paste': ['pace'],
   362→    'select': ['salect', 'select the'],
   363→    'save': ['saev'],
   364→    'close': ['clothes', 'close the'],
   365→    'scroll': ['skroll'],
   366→    'format': ['form at'],
   367→    'indent': ['in dent'],
   368→    'tab': ['tabb']
   369→};
   370→
   371→/**
   372→ * Normalize text by applying homophone corrections.
   373→ */
   374→export function normalizeCommand(text: string): string {
   375→    let normalized = text.toLowerCase();
   376→    for (const [correct, variants] of Object.entries(HOMOPHONES)) {
   377→        for (const variant of variants) {
   378→            normalized = normalized.replace(variant, correct);
   379→        }
   380→    }
   381→    return normalized;
   382→}
   383→
   384→/**
   385→ * Process transcription and execute commands.
   386→ * Full pipeline from ADR-008.
   387→ */
   388→export async function processTranscription(rawText: string): Promise<void> {
   389→    const parser = new CommandParser();
   390→    const executor = new CommandExecutor();
   391→
   392→    // Parse commands
   393→    const parsed = parser.parse(rawText);
   394→
   395→    // Insert text (if any)
   396→    if (parsed.text) {
   397→        await insertText(parsed.text);
   398→    }
   399→
   400→    // Execute commands
   401→    for (const cmd of parsed.commands) {
   402→        await executor.execute(cmd);
   403→    }
   404→}
   405→
   406→/**
   407→ * Insert text at cursor position.
   408→ */
   409→async function insertText(text: string): Promise<void> {
   410→    const editor = vscode.window.activeTextEditor;
   411→    if (!editor) {
   412→        return;
   413→    }
   414→
   415→    await editor.edit(editBuilder => {
   416→        editBuilder.insert(editor.selection.active, text);
   417→    });
   418→}
   419→
   420→// Export default parser instance
   421→export const commandParser = new CommandParser();
   422→export const commandExecutor = new CommandExecutor();
   423→

