     1→/**
     2→ * Audio Streamer
     3→ * Handles streaming audio data to the backend via WebSocket
     4→ * Per ADR-004: Audio Streaming Protocol
     5→ *
     6→ * Extended to handle interim/streaming/final messages (ADR-006, ADR-007)
     7→ * Extended with error handling and circuit breaker (ADR-015)
     8→ */
     9→
    10→import type { ServerMessage } from './textInsertion';
    11→import {
    12→    calculateBackoff,
    13→    CircuitBreaker,
    14→    ConnectionError,
    15→    ConnectionState,
    16→    getCircuitBreaker,
    17→    type ReconnectConfig,
    18→} from './errorHandling';
    19→
    20→export interface AudioStreamerOptions {
    21→    readonly sampleRate: number;
    22→    readonly channels: number;
    23→    readonly reconnectConfig?: Partial<ReconnectConfig>;
    24→}
    25→
    26→export interface AudioStreamerEvents {
    27→    onConnected?: () => void;
    28→    onDisconnected?: () => void;
    29→    onError?: (error: Error) => void;
    30→    onMessage?: (message: ServerMessage) => void;
    31→    onReconnecting?: (attempt: number) => void;
    32→}
    33→
    34→/**
    35→ * Audio Streamer Class
    36→ * Converts Float32Array audio samples to PCM16 and streams via WebSocket
    37→ * Handles server messages for interim, streaming, and final results
    38→ * Implements circuit breaker and automatic reconnection
    39→ */
    40→export class AudioStreamer {
    41→    private ws: WebSocket | null = null;
    42→    private url: string;
    43→    private options: AudioStreamerOptions;
    44→    private events: AudioStreamerEvents;
    45→    private isStreaming: boolean = false;
    46→
    47→    // Connection state and reconnection tracking
    48→    private connectionState: ConnectionState = {
    49→        status: 'disconnected',
    50→        lastError: null,
    51→        reconnectAttempts: 0,
    52→    };
    53→
    54→    private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
    55→    private circuitBreaker: CircuitBreaker;
    56→
    57→    constructor(url: string, options: AudioStreamerOptions, events: AudioStreamerEvents = {}) {
    58→        this.url = url;
    59→        this.options = options;
    60→        this.events = events;
    61→
    62→        // Initialize circuit breaker for WebSocket connections
    63→        this.circuitBreaker = getCircuitBreaker('websocket', {
    64→            failureThreshold: 5,
    65→            resetTimeout: 30000,
    66→            successThreshold: 2,
    67→        });
    68→    }
    69→
    70→    /**
    71→     * Connect to the WebSocket server with circuit breaker protection.
    72→     */
    73→    public connect(): Promise<void> {
    74→        return this.circuitBreaker.execute(async () => {
    75→            return new Promise((resolve, reject) => {
    76→                try {
    77→                    this.connectionState.status = 'connecting';
    78→                    this.ws = new WebSocket(this.url);
    79→                    this.isStreaming = false;
    80→
    81→                    this.ws.onopen = () => {
    82→                        this.connectionState.status = 'connected';
    83→                        this.connectionState.reconnectAttempts = 0;
    84→                        this.connectionState.lastError = null;
    85→                        this.isStreaming = true;
    86→
    87→                        this.circuitBreaker.onSuccess();
    88→                        this.events.onConnected?.();
    89→                        resolve();
    90→                    };
    91→
    92→                    this.ws.onerror = (event) => {
    93→                        const error = new ConnectionError('WebSocket connection error');
    94→                        this.circuitBreaker.onFailure();
    95→                        this.events.onError?.(error);
    96→                        reject(error);
    97→                    };
    98→
    99→                    this.ws.onclose = (event) => {
   100→                        this.isStreaming = false;
   101→                        this.connectionState.status = 'disconnected';
   102→
   103→                        // Attempt reconnection on abnormal close
   104→                        if (event.code !== 1000) {
   105→                            this.handleDisconnect(new ConnectionError(
   106→                                `WebSocket closed: ${event.reason || 'Unknown reason'}`
   107→                            ));
   108→                        }
   109→
   110→                        this.events.onDisconnected?.();
   111→                    };
   112→
   113→                    this.ws.onmessage = (event) => {
   114→                        this.handleMessage(event);
   115→                    };
   116→
   117→                } catch (error) {
   118→                    const err = error instanceof Error ? error : new Error('Failed to create WebSocket');
   119→                    this.circuitBreaker.onFailure();
   120→                    this.events.onError?.(err);
   121→                    reject(err);
   122→                }
   123→            });
   124→        });
   125→    }
   126→
   127→    /**
   128→     * Handle disconnection with reconnection logic.
   129→     */
   130→    private handleDisconnect(error: Error): void {
   131→        this.connectionState.lastError = error;
   132→
   133→        // Clear any existing reconnect timer
   134→        if (this.reconnectTimer) {
   135→            clearTimeout(this.reconnectTimer);
   136→            this.reconnectTimer = null;
   137→        }
   138→
   139→        // Check circuit breaker and reconnection limits
   140→        if (!this.circuitBreaker.canExecute()) {
   141→            this.events.onError?.(new Error('Service temporarily unavailable (circuit open)'));
   142→            return;
   143→        }
   144→
   145→        const reconnectConfig = {
   146→            maxReconnectAttempts: 5,
   147→            baseDelay: 1000,
   148→            maxDelay: 30000,
   149→            ...this.options.reconnectConfig,
   150→        };
   151→
   152→        if (this.connectionState.reconnectAttempts >= reconnectConfig.maxReconnectAttempts) {
   153→            this.events.onError?.(new Error('Max reconnection attempts reached'));
   154→            return;
   155→        }
   156→
   157→        // Schedule reconnection with exponential backoff
   158→        const delay = calculateBackoff(this.connectionState.reconnectAttempts, reconnectConfig);
   159→        this.connectionState.status = 'reconnecting';
   160→        this.connectionState.reconnectAttempts++;
   161→
   162→        this.events.onReconnecting?.(this.connectionState.reconnectAttempts);
   163→
   164→        this.reconnectTimer = setTimeout(() => {
   165→            this.connect().catch(err => {
   166→                // Will trigger handleDisconnect again if it fails
   167→            });
   168→        }, delay);
   169→    }
   170→
   171→    /**
   172→     * Handle incoming WebSocket message
   173→     */
   174→    private handleMessage(event: MessageEvent): void {
   175→        try {
   176→            const message = JSON.parse(event.data) as ServerMessage;
   177→            this.events.onMessage?.(message);
   178→        } catch (error) {
   179→            console.error('Failed to parse WebSocket message:', error);
   180→        }
   181→    }
   182→
   183→    /**
   184→     * Send audio data to the server
   185→     * Converts Float32Array (-1.0 to 1.0) to PCM16 Int16Array
   186→     */
   187→    public sendAudio(samples: Float32Array): void {
   188→        if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
   189→            throw new Error('WebSocket is not connected');
   190→        }
   191→
   192→        // Convert Float32Array (-1.0 to 1.0) to Int16Array (-32768 to 32767)
   193→        const pcm16 = new Int16Array(samples.length);
   194→        for (let i = 0; i < samples.length; i++) {
   195→            const sample = Math.max(-1, Math.min(1, samples[i]));
   196→            pcm16[i] = sample < 0 ? sample * 0x8000 : sample * 0x7FFF;
   197→        }
   198→
   199→        // Send as binary frame
   200→        this.ws.send(pcm16.buffer);
   201→    }
   202→
   203→    /**
   204→     * Send control message to server
   205→     */
   206→    public sendControl(type: string, data?: Record<string, unknown>): void {
   207→        if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
   208→            throw new Error('WebSocket is not connected');
   209→        }
   210→
   211→        const message = { type, ...data };
   212→        this.ws.send(JSON.stringify(message));
   213→    }
   214→
   215→    /**
   216→     * Send start recording signal
   217→     */
   218→    public startRecording(): void {
   219→        this.sendControl('start');
   220→    }
   221→
   222→    /**
   223→     * Send stop recording signal
   224→     */
   225→    public stopRecording(): void {
   226→        this.sendControl('stop');
   227→    }
   228→
   229→    /**
   230→     * Send ping for heartbeat
   231→     */
   232→    public ping(): void {
   233→        this.sendControl('ping');
   234→    }
   235→
   236→    /**
   237→     * Send end-of-stream signal (deprecated - use stopRecording)
   238→     */
   239→    public sendEndOfStream(): void {
   240→        this.stopRecording();
   241→    }
   242→
   243→    /**
   244→     * Close the connection and stop reconnection attempts.
   245→     */
   246→    public close(): void {
   247→        // Clear reconnect timer
   248→        if (this.reconnectTimer) {
   249→            clearTimeout(this.reconnectTimer);
   250→            this.reconnectTimer = null;
   251→        }
   252→
   253→        // Close WebSocket
   254→        if (this.ws) {
   255→            this.ws.close(1000, 'Client closing');
   256→            this.ws = null;
   257→        }
   258→
   259→        this.isStreaming = false;
   260→        this.connectionState.status = 'disconnected';
   261→    }
   262→
   263→    /**
   264→     * Check if connected and streaming
   265→     */
   266→    public get isConnected(): boolean {
   267→        return this.isStreaming;
   268→    }
   269→
   270→    /**
   271→     * Get WebSocket ready state
   272→     */
   273→    public get readyState(): number {
   274→        return this.ws?.readyState ?? WebSocket.CLOSED;
   275→    }
   276→}
   277→

