   229→    /**
   230→     * Test voice command parser
   231→     */
   232→    private async testVoiceCommands(): Promise<void> {
   233→        const parser = CommandParser.withSettings();
   234→        const results = runCommandParserTests(parser);
   235→
   236→        const output = formatTestResults(results);
   237→        this.outputChannel.clear();
   238→        this.outputChannel.append(output);
