   295→    /**
   296→     * List all available voice commands (ADR-008)
   297→     */
   298→    private async listVoiceCommands(): Promise<void> {
   299→        const parser = CommandParser.withSettings();
   300→        const commands = parser.getCommandList();
   301→
   302→        // Group commands by category
   303→        const categories = new Map<string, typeof commands>();
   304→        for (const cmd of commands) {
   305→            const category = this.categorizeCommand(cmd.action);
   306→            if (!categories.has(category)) {
   307→                categories.set(category, []);
   308→            }
   309→            categories.get(category)!.push(cmd);
   310→        }
   311→
   312→        // Build formatted message
   313→        let message = 'VTThought Voice Commands\n\n';
   314→        for (const [category, cmds] of categories.entries()) {
   315→            message += `## ${category}\n`;
   316→            for (const cmd of cmds) {
   317→                const triggers = cmd.trigger.join(', ');
   318→                message += `  • "${triggers}" → ${cmd.action}\n`;
   319→            }
   320→            message += '\n';
   321→        }
   322→
   323→        // Show in output channel
   324→        this.outputChannel.clear();
   325→        this.outputChannel.append(message);
   326→        this.outputChannel.show();
   327→
   328→        vscode.window.showInformationMessage(
   329→            'Voice commands listed in VTThought output channel'
   330→        );
