   332→
   333→    private categorizeCommand(action: string): string {
   334→        if (action.startsWith('terminal.')) return 'Execution Commands';
   335→        if (action.startsWith('editor.action') || action === 'undo' || action === 'redo' || action === 'type') return 'Editing Commands';
   336→        if (action === 'workbench.action.gotoLine' || action === 'editorScroll' || action === 'cursorHome' || action === 'cursorEnd') return 'Navigation Commands';
   337→        if (action.startsWith('workbench.action') || action.startsWith('workbench.view')) return 'VS Code Commands';
   338→        if (action === 'vtthought.toggleRecording') return 'Dictation Control';
   339→        return 'Other';
   340→    }
