   501→    private async clearAuthentication(): Promise<void> {
   502→        const result = await vscode.window.showWarningMessage(
   503→            'Are you sure you want to clear your authentication settings?',
   504→            { modal: true },
   505→            'Clear',
   506→            'Cancel'
   507→        );
   508→
   509→        if (result === 'Clear') {
