   728→    /**
   729→     * Disconnect from backend
   730→     */
   731→    private disconnect(): void {
   732→        // Stop recording if active
   733→        if (this.state.isRecording) {
   734→            this.stopRecording();
   735→        }
   736→
   737→        // Close WebSocket connection
   738→        if (this.audioStreamer) {
