     1→/**
     2→ * VTThought Edit Detection Module (ADR-011)
     3→ *
     4→ * Tracks user edits to transcribed text for style learning.
     5→ * Detects when users modify transcribed text and reports changes.
     6→ */
     7→
     8→import * as vscode from 'vscode';
     9→
    10→/**
    11→ * Edit event representing a user change to transcribed text.
    12→ */
    13→export interface EditEvent {
    14→    before: string;
    15→    after: string;
    16→    timestamp: number;
    17→    documentUri: string;
    18→}
    19→
    20→/**
    21→ * Configuration for edit detection.
    22→ */
    23→export interface EditDetectionConfig {
    24→    /**
    25→     * Minimum time after insertion to consider edits as "learning edits".
    26→     * Edits within this window are part of the dictation session.
    27→     */
    28→    learningWindowMs: number;
    29→
    30→    /**
    31→     * Maximum length of text to track for learning.
    32→     * Longer texts are not tracked to avoid false positives.
    33→     */
    34→    maxTrackLength: number;
    35→
    36→    /**
    37→     * Enable/disable edit learning.
    38→     */
    39→    enabled: boolean;
    40→}
    41→
    42→/**
    43→ * Default configuration.
    44→ */
    45→const DEFAULT_CONFIG: EditDetectionConfig = {
    46→    learningWindowMs: 30000, // 30 seconds
    47→    maxTrackLength: 500, // characters
    48→    enabled: true,
    49→};
    50→
    51→/**
    52→ * Tracks text insertions for potential edit learning.
    53→ */
    54→interface InsertionTrack {
    55→    text: string;
    56→    timestamp: number;
    57→    documentUri: string;
    58→    range: vscode.Range;
    59→}
    60→
    61→/**
    62→ * Edit detector for learning user preferences.
    63→ *
    64→ * Tracks text insertions from dictation and detects subsequent edits
    65→ * to learn user style preferences.
    66→ */
    67→export class EditDetector {
    68→    private trackedInsertions = new Map<string, InsertionTrack>();
    69→    private disposables: vscode.Disposable[] = [];
    70→    private config: EditDetectionConfig;
    71→
    72→    /**
    73→     * Create an EditDetector instance.
    74→     *
    75→     * @param config - Configuration options
    76→     */
    77→    constructor(config: Partial<EditDetectionConfig> = {}) {
    78→        this.config = { ...DEFAULT_CONFIG, ...config };
    79→        this.setupEventHandlers();
    80→    }
    81→
    82→    /**
    83→     * Set up VS Code event handlers for edit detection.
    84→     */
    85→    private setupEventHandlers(): void {
    86→        // Track text document changes
    87→        const changeTracker = vscode.workspace.onDidChangeTextDocument((event) => {
    88→            this.handleDocumentChange(event);
    89→        });
    90→
    91→        this.disposables.push(changeTracker);
    92→    }
    93→
    94→    /**
    95→     * Handle text document change events.
    96→     */
    97→    private handleDocumentChange(event: vscode.TextDocumentChangeEvent): void {
    98→        if (!this.config.enabled) {
    99→            return;
   100→        }
   101→
   102→        // Check if this document has tracked insertions
   103→        const uri = event.document.uri.toString();
   104→        const relevantTracks = this.getRelevantTracks(uri, event.contentChanges);
   105→
   106→        if (relevantTracks.length === 0) {
   107→            return;
   108→        }
   109→
   110→        // Process each relevant change
   111→        for (const change of event.contentChanges) {
   112→            for (const track of relevantTracks) {
   113→                if (this.doesChangeAffectTrack(change, track)) {
   114→                    this.processEdit(track, change, event.document);
   115→                }
   116→            }
   117→        }
   118→
   119→        // Clean up old tracks
   120→        this.cleanupOldTracks();
   121→    }
   122→
   123→    /**
   124→     * Get tracks that may be affected by the content changes.
   125→     */
   126→    private getRelevantTracks(
   127→        documentUri: string,
   128→        changes: readonly vscode.TextDocumentContentChangeEvent[]
   129→    ): InsertionTrack[] {
   130→        const uri = documentUri;
   131→        const tracks: InsertionTrack[] = [];
   132→
   133→        for (const track of this.trackedInsertions.values()) {
   134→            if (track.documentUri !== uri) {
   135→                continue;
   136→            }
   137→
   138→            // Check if any change overlaps with the tracked range
   139→            for (const change of changes) {
   140→                const changeRange = change.range;
   141→                const trackRange = track.range;
   142→
   143→                if (this.rangesOverlap(changeRange, trackRange)) {
   144→                    tracks.push(track);
   145→                    break;
   146→                }
   147→            }
   148→        }
   149→
   150→        return tracks;
   151→    }
   152→
   153→    /**
   154→     * Check if two ranges overlap.
   155→     */
   156→    private rangesOverlap(range1: vscode.Range, range2: vscode.Range): boolean {
   157→        return !(range1.end.isBefore(range2.start) || range1.start.isAfter(range2.end));
   158→    }
   159→
   160→    /**
   161→     * Check if a change affects a tracked insertion.
   162→     */
   163→    private doesChangeAffectTrack(
   164→        change: vscode.TextDocumentContentChangeEvent,
   165→        track: InsertionTrack
   166→    ): boolean {
   167→        return this.rangesOverlap(change.range, track.range);
   168→    }
   169→
   170→    /**
   171→     * Process an edit to tracked text.
   172→     */
   173→    private processEdit(
   174→        track: InsertionTrack,
   175→        change: vscode.TextDocumentContentChangeEvent,
   176→        document: vscode.TextDocument
   177→    ): void {
   178→        const now = Date.now();
   179→        const timeSinceInsertion = now - track.timestamp;
   180→
   181→        // Only process edits within the learning window
   182→        if (timeSinceInsertion > this.config.learningWindowMs) {
   183→            this.trackedInsertions.delete(this.getTrackKey(track));
   184→            return;
   185→        }
   186→
   187→        // Get the current text in the tracked range
   188→        let currentText: string;
   189→        try {
   190→            currentText = document.getText(track.range);
   191→        } catch {
   192→            // Range may be invalid if document was heavily edited
   193→            this.trackedInsertions.delete(this.getTrackKey(track));
   194→            return;
   195→        }
   196→
   197→        // Skip if text hasn't meaningfully changed
   198→        if (currentText === track.text) {
   199→            return;
   200→        }
   201→
   202→        // Normalize for comparison (whitespace, case for some scenarios)
   203→        const before = this.normalizeForLearning(track.text);
   204→        const after = this.normalizeForLearning(currentText);
   205→
   206→        if (before === after) {
   207→            return;
   208→        }
   209→
   210→        // Emit edit event
   211→        this.onEditDetected({
   212→            before: track.text,
   213→            after: currentText,
   214→            timestamp: now,
   215→            documentUri: track.documentUri,
   216→        });
   217→
   218→        // Remove track after processing (one learning event per insertion)
   219→        this.trackedInsertions.delete(this.getTrackKey(track));
   220→    }
   221→
   222→    /**
   223→     * Normalize text for learning comparison.
   224→     */
   225→    private normalizeForLearning(text: string): string {
   226→        return text.trim();
   227→    }
   228→
   229→    /**
   230→     * Get a unique key for a track.
   231→     */
   232→    private getTrackKey(track: InsertionTrack): string {
   233→        return `${track.documentUri}:${track.range.start.line}:${track.range.start.character}:${track.timestamp}`;
   234→    }
   235→
   236→    /**
   237→     * Clean up old tracked insertions.
   238→     */
   239→    private cleanupOldTracks(): void {
   240→        const now = Date.now();
   241→        const maxAge = this.config.learningWindowMs * 2; // Keep for 2x the window
   242→
   243→        for (const [key, track] of this.trackedInsertions.entries()) {
   244→            if (now - track.timestamp > maxAge) {
   245→                this.trackedInsertions.delete(key);
   246→            }
   247→        }
   248→    }
   249→
   250→    /**
   251→     * Track a text insertion for potential edit learning.
   252→     *
   253→     * Call this when inserting transcribed text.
   254→     *
   255→     * @param text - The inserted text
   256→     * @param range - The range where text was inserted
   257→     * @param documentUri - The document URI
   258→     */
   259→    trackInsertion(text: string, range: vscode.Range, documentUri: string): void {
   260→        if (!this.config.enabled) {
   261→            return;
   262→        }
   263→
   264→        // Skip tracking very long texts
   265→        if (text.length > this.config.maxTrackLength) {
   266→            return;
   267→        }
   268→
   269→        // Skip tracking if text is too short
   270→        if (text.length < 10) {
   271→            return;
   272→        }
   273→
   274→        // Skip tracking if text is mostly whitespace
   275→        const trimmed = text.trim();
   276→        if (trimmed.length < text.length * 0.5) {
   277→            return;
   278→        }
   279→
   280→        const track: InsertionTrack = {
   281→            text,
   282→            timestamp: Date.now(),
   283→            documentUri,
   284→            range,
   285→        };
   286→
   287→        const key = this.getTrackKey(track);
   288→        this.trackedInsertions.set(key, track);
   289→    }
   290→
   291→    /**
   292→     * Edit detected event callback.
   293→     * Override this to handle edit events.
   294→     */
   295→    protected onEditDetected(event: EditEvent): void {
   296→        // Default: do nothing, override for custom handling
   297→    }
   298→
   299→    /**
   300→     * Update configuration.
   301→     */
   302→    updateConfig(config: Partial<EditDetectionConfig>): void {
   303→        this.config = { ...this.config, ...config };
   304→    }
   305→
   306→    /**
   307→     * Get current configuration.
   308→     */
   309→    getConfig(): EditDetectionConfig {
   310→        return { ...this.config };
   311→    }
   312→
   313→    /**
   314→     * Clear all tracked insertions.
   315→     */
   316→    clearTrackedInsertions(): void {
   317→        this.trackedInsertions.clear();
   318→    }
   319→
   320→    /**
   321→     * Get count of currently tracked insertions.
   322→     */
   323→    getTrackedCount(): number {
   324→        return this.trackedInsertions.size;
   325→    }
   326→
   327→    /**
   328→     * Dispose resources.
   329→     */
   330→    dispose(): void {
   331→        for (const disposable of this.disposables) {
   332→            disposable.dispose();
   333→        }
   334→        this.disposables = [];
   335→        this.trackedInsertions.clear();
   336→    }
   337→}
   338→
   339→/**
   340→ * Edit detector with callback for reporting edits to backend.
   341→ */
   342→export class ReportingEditDetector extends EditDetector {
   343→    private editCallback: (event: EditEvent) => void;
   344→
   345→    /**
   346→     * Create a ReportingEditDetector instance.
   347→     *
   348→     * @param editCallback - Callback to handle edit events (can be async)
   349→     * @param config - Configuration options
   350→     */
   351→    constructor(
   352→        editCallback: (event: EditEvent) => void | Promise<void>,
   353→        config: Partial<EditDetectionConfig> = {}
   354→    ) {
   355→        super(config);
   356→        // Wrap async callback to make it fire-and-forget
   357→        this.editCallback = (event) => {
   358→            // Don't await - let it run in background
   359→            Promise.resolve(editCallback(event)).catch(err => {
   360→                console.error('Edit callback error:', err);
   361→            });
   362→        };
   363→    }
   364→
   365→    /**
   366→     * Handle edit detected event by calling the callback.
   367→     */
   368→    protected onEditDetected(event: EditEvent): void {
   369→        this.editCallback(event);
   370→    }
   371→}
   372→
   373→/**
   374→ * Create an edit detector integrated with UserPreferencesManager.
   375→ *
   376→ * @param preferencesManager - The preferences manager to report edits to
   377→ * @param config - Configuration options
   378→ * @returns Configured edit detector
   379→ */
   380→export function createEditDetector(
   381→    preferencesManager: import('./userPreferences').UserPreferencesManager,
   382→    config: Partial<EditDetectionConfig> = {}
   383→): ReportingEditDetector {
   384→    return new ReportingEditDetector(
   385→        async (event) => {
   386→            await preferencesManager.reportEdit(event.before, event.after);
   387→        },
   388→        config
   389→    );
   390→}
