     1→/**
     2→ * VTThought User Preferences Module (ADR-011)
     3→ *
     4→ * Manages user vocabulary, style preferences, and learned corrections
     5→ * by communicating with the backend API.
     6→ */
     7→
     8→import * as vscode from 'vscode';
     9→import { createEditDetector, EditDetector } from './editDetection';
    10→
    11→/**
    12→ * Vocabulary term category.
    13→ */
    14→export type VocabularyCategory = 'technical' | 'project' | 'names' | 'acronyms' | 'general';
    15→
    16→/**
    17→ * A vocabulary term for Whisper biasing.
    18→ */
    19→export interface VocabularyTerm {
    20→    word: string;
    21→    category: VocabularyCategory;
    22→    phonetic_hint?: string;
    23→    created_at?: string;
    24→}
    25→
    26→/**
    27→ * A learned correction from user edits.
    28→ */
    29→export interface LearnedCorrection {
    30→    original: string;
    31→    corrected: string;
    32→    occurrence_count: number;
    33→    last_seen?: string;
    34→}
    35→
    36→/**
    37→ * Punctuation preference.
    38→ */
    39→export type PunctuationStyle = 'standard' | 'minimal' | 'oxford_comma' | 'em_dash';
    40→
    41→/**
    42→ * Capitalization preference.
    43→ */
    44→export type CapitalizationStyle = 'standard' | 'sentence' | 'title';
    45→
    46→/**
    47→ * Number format preference.
    48→ */
    49→export type NumberStyle = 'digits' | 'words' | 'scientific';
    50→
    51→/**
    52→ * Style preferences for text cleanup.
    53→ */
    54→export interface StylePreferences {
    55→    punctuation_style: PunctuationStyle;
    56→    capitalization: CapitalizationStyle;
    57→    number_format: NumberStyle;
    58→    use_abbreviations: boolean;
    59→    oxford_comma: boolean;
    60→    confidence_score?: number;
    61→}
    62→
    63→/**
    64→ * User preferences summary.
    65→ */
    66→export interface UserPreferences {
    67→    language: string;
    68→    cleanup_level: 'light' | 'medium' | 'aggressive';
    69→    hotkey_mode: 'push_to_talk' | 'toggle';
    70→}
    71→
    72→/**
    73→ * API client for user preferences.
    74→ */
    75→export class UserPreferencesClient {
    76→    private constructor(
    77→        private readonly apiUrl: string,
    78→        private readonly getAuthHeader: () => Promise<string | undefined>
    79→    ) {}
    80→
    81→    /**
    82→     * Create a UserPreferencesClient instance.
    83→     *
    84→     * @param apiUrl - Base API URL
    85→     * @param getAuthHeader - Function to get authorization header
    86→     * @returns UserPreferencesClient instance
    87→     */
    88→    public static create(
    89→        apiUrl: string,
    90→        getAuthHeader: () => Promise<string | undefined>
    91→    ): UserPreferencesClient {
    92→        return new UserPreferencesClient(apiUrl, getAuthHeader);
    93→    }
    94→
    95→    /**
    96→     * Make an authenticated API request.
    97→     */
    98→    private async request<T>(
    99→        path: string,
   100→        options: RequestInit = {}
   101→    ): Promise<T> {
   102→        const authHeader = await this.getAuthHeader();
   103→        if (!authHeader) {
   104→            throw new Error('Not authenticated');
   105→        }
   106→
   107→        const url = `${this.apiUrl}${path}`;
   108→        const response = await fetch(url, {
   109→            ...options,
   110→            headers: {
   111→                'Authorization': authHeader,
   112→                'Content-Type': 'application/json',
   113→                ...options.headers,
   114→            },
   115→        });
   116→
   117→        if (!response.ok) {
   118→            const error = await response.text().catch(() => 'Unknown error');
   119→            throw new Error(`API error (${response.status}): ${error}`);
   120→        }
   121→
   122→        return response.json() as Promise<T>;
   123→    }
   124→
   125→    /**
   126→     * Get all vocabulary terms.
   127→     */
   128→    async getVocabulary(): Promise<VocabularyTerm[]> {
   129→        return this.request<VocabularyTerm[]>('/api/user/vocabulary');
   130→    }
   131→
   132→    /**
   133→     * Add a vocabulary term.
   134→     *
   135→     * @param word - The word to add
   136→     * @param category - The category of the word
   137→     * @param phoneticHint - Optional phonetic hint
   138→     */
   139→    async addVocabularyTerm(
   140→        word: string,
   141→        category: VocabularyCategory = 'general',
   142→        phoneticHint?: string
   143→    ): Promise<VocabularyTerm> {
   144→        return this.request<VocabularyTerm>('/api/user/vocabulary', {
   145→            method: 'POST',
   146→            body: JSON.stringify({
   147→                word,
   148→                category,
   149→                phonetic_hint: phoneticHint,
   150→            }),
   151→        });
   152→    }
   153→
   154→    /**
