   263→export class UserPreferencesManager {
   264→    private client: UserPreferencesClient | null = null;
   265→    private outputChannel: vscode.OutputChannel;
   266→
   267→    private constructor(
   268→        private readonly context: vscode.ExtensionContext,
   269→        private readonly getAuthHeader: () => Promise<string | undefined>
   270→    ) {
   271→        this.outputChannel = vscode.window.createOutputChannel('VTThought Preferences');
   272→    }
   273→
   274→    /**
   275→     * Create a UserPreferencesManager instance.
   276→     */
   277→    public static create(
   278→        context: vscode.ExtensionContext,
   279→        getAuthHeader: () => Promise<string | undefined>
   280→    ): UserPreferencesManager {
   281→        return new UserPreferencesManager(context, getAuthHeader);
   282→    }
   283→
   284→    /**
   285→     * Get the API client, initializing if necessary.
   286→     */
   287→    private async getClient(): Promise<UserPreferencesClient> {
   288→        if (!this.client) {
   289→            const config = vscode.workspace.getConfiguration('vtthought');
   290→            const apiUrl = config.get<string>('apiUrl', 'http://localhost:8000');
   291→            this.client = UserPreferencesClient.create(apiUrl, this.getAuthHeader);
   292→        }
   293→        return this.client;
   294→    }
   295→
   296→    /**
   297→     * Log to output channel.
   298→     */
   299→    private log(message: string): void {
   300→        const timestamp = new Date().toLocaleTimeString();
   301→        this.outputChannel.appendLine(`[${timestamp}] ${message}`);
   302→    }
   303→
   304→    /**
   305→     * Show vocabulary management QuickPick.
   306→     */
   307→    async manageVocabulary(): Promise<void> {
   308→        const client = await this.getClient();
   309→
   310→        try {
   311→            const vocabulary = await client.getVocabulary();
   312→
   313→            if (vocabulary.length === 0) {
   314→                const result = await vscode.window.showQuickPick(
   315→                    ['Add a vocabulary term', 'Cancel'],
   316→                    {
   317→                        title: 'VTThought Vocabulary',
   318→                        placeHolder: 'No vocabulary terms yet. Add one to get started.',
   319→                    }
   320→                );
   321→
   322→                if (result === 'Add a vocabulary term') {
   323→                    await this.addVocabularyTerm();
   324→                }
   325→                return;
   326→            }
   327→
   328→            // Create QuickPick items with categories
   329→            const items: vscode.QuickPickItem[] = vocabulary.map((term) => ({
   330→                label: term.word,
   331→                description: this.getCategoryIcon(term.category) + ' ' + term.category,
   332→                detail: term.phonetic_hint ? `Phonetic: ${term.phonetic_hint}` : undefined,
   333→            }));
   334→
   335→            // Add management options at the top
   336→            items.unshift(
   337→                { label: '$(plus) Add Vocabulary Term', description: 'Add a new word or phrase' },
   338→                { label: '$(x) Remove Multiple Terms', description: 'Bulk remove vocabulary terms' },
   339→                { label: '$(refresh) Refresh', description: 'Reload vocabulary from server' }
   340→            );
   341→
   342→            const selection = await vscode.window.showQuickPick(items, {
   343→                title: `VTThought Vocabulary (${vocabulary.length} terms)`,
   344→                placeHolder: 'Select a term to manage or add a new one',
   345→            });
   346→
   347→            if (!selection) {
   348→                return;
   349→            }
   350→
   351→            if (selection.label === '$(plus) Add Vocabulary Term') {
   352→                await this.addVocabularyTerm();
   353→            } else if (selection.label === '$(x) Remove Multiple Terms') {
   354→                await this.removeMultipleVocabularyTerms(vocabulary);
   355→            } else if (selection.label === '$(refresh) Refresh') {
   356→                vscode.window.showInformationMessage('Vocabulary refreshed');
   357→            } else {
   358→                // Show term details
   359→                await this.manageVocabularyTerm(selection.label);
   360→            }
   361→        } catch (error) {
   362→            this.log(`Error loading vocabulary: ${error}`);
   363→            vscode.window.showErrorMessage(
   364→                `Failed to load vocabulary: ${error instanceof Error ? error.message : String(error)}`
   365→            );
   366→        }
   367→    }
   368→
   369→    /**
   370→     * Get icon for vocabulary category.
   371→     */
   372→    private getCategoryIcon(category: VocabularyCategory): string {
   373→        const icons: Record<VocabularyCategory, string> = {
   374→            technical: '$(symbol-code)',
   375→            project: '$(folder)',
   376→            names: '$(account)',
   377→            acronyms: '$(symbol-keyword)',
   378→            general: '$(tag)',
   379→        };
   380→        return icons[category] || '$(tag)';
   381→    }
