   383→    /**
   384→     * Add a new vocabulary term.
   385→     */
   386→    private async addVocabularyTerm(): Promise<void> {
   387→        // Get word from user
   388→        const word = await vscode.window.showInputBox({
   389→            title: 'Add Vocabulary Term',
   390→            placeHolder: 'Enter the word or phrase',
   391→            prompt: 'Enter the word or phrase to add to your vocabulary',
   392→            validateInput: (value) => {
   393→                if (!value || value.trim().length === 0) {
   394→                    return 'Please enter a word or phrase';
   395→                }
   396→                return null;
   397→            },
   398→        });
   399→
   400→        if (!word) {
   401→            return;
   402→        }
   403→
   404→        // Get category from user
   405→        const categoryItems: vscode.QuickPickItem[] = [
   406→            { label: 'Technical', description: 'Code terms, APIs, libraries' },
   407→            { label: 'Project', description: 'Project-specific terms' },
   408→            { label: 'Names', description: 'People, usernames' },
   409→            { label: 'Acronyms', description: 'Abbreviations and acronyms' },
   410→            { label: 'General', description: 'Other vocabulary' },
   411→        ];
   412→
   413→        const categorySelection = await vscode.window.showQuickPick(categoryItems, {
   414→            title: 'Select Category',
   415→            placeHolder: 'Choose a category for this term',
   416→        });
   417→
   418→        if (!categorySelection) {
   419→            return;
   420→        }
   421→
   422→        const category = categorySelection.label.toLowerCase() as VocabularyCategory;
   423→
   424→        // Optionally get phonetic hint
   425→        const addPhonetic = await vscode.window.showQuickPick(
   426→            ['Yes, add phonetic hint', 'No, skip'],
   427→            {
   428→                title: 'Add Phonetic Hint',
   429→                placeHolder: 'Would you like to add a phonetic hint?',
   430→            }
   431→        );
   432→
   433→        let phoneticHint: string | undefined;
   434→        if (addPhonetic === 'Yes, add phonetic hint') {
   435→            phoneticHint = await vscode.window.showInputBox({
   436→                title: 'Phonetic Hint',
   437→                placeHolder: 'Enter phonetic pronunciation (e.g., "GOO-gul")',
   438→                prompt: 'Enter how the word should be pronounced',
   439→            });
   440→        }
   441→
   442→        try {
   443→            const client = await this.getClient();
   444→            await client.addVocabularyTerm(word.trim(), category, phoneticHint);
   445→            this.log(`Added vocabulary term: ${word}`);
   446→            vscode.window.showInformationMessage(`Added "${word}" to vocabulary`);
   447→        } catch (error) {
   448→            this.log(`Error adding vocabulary term: ${error}`);
   449→            vscode.window.showErrorMessage(
   450→                `Failed to add vocabulary term: ${error instanceof Error ? error.message : String(error)}`
   451→            );
   452→        }
   453→    }
   454→
   455→    /**
   456→     * Manage a specific vocabulary term.
   457→     */
   458→    private async manageVocabularyTerm(word: string): Promise<void> {
   459→        const options = [
   460→            { label: '$(x) Remove', description: 'Remove this term from vocabulary' },
   461→            { label: '$(pencil) Edit Phonetic Hint', description: 'Change the phonetic hint' },
   462→        ];
   463→
   464→        const selection = await vscode.window.showQuickPick(options, {
   465→            title: word,
   466→            placeHolder: 'What would you like to do with this term?',
   467→        });
   468→
   469→        if (!selection) {
   470→            return;
   471→        }
   472→
   473→        if (selection.label.startsWith('$(x)')) {
   474→            const confirmed = await vscode.window.showWarningMessage(
   475→                `Remove "${word}" from vocabulary?`,
   476→                { modal: true },
   477→                'Remove',
   478→                'Cancel'
   479→            );
   480→
   481→            if (confirmed === 'Remove') {
   482→                try {
   483→                    const client = await this.getClient();
   484→                    await client.removeVocabularyTerm(word);
   485→                    this.log(`Removed vocabulary term: ${word}`);
   486→                    vscode.window.showInformationMessage(`Removed "${word}" from vocabulary`);
   487→                } catch (error) {
   488→                    this.log(`Error removing vocabulary term: ${error}`);
   489→                    vscode.window.showErrorMessage(
   490→                        `Failed to remove vocabulary term: ${error instanceof Error ? error.message : String(error)}`
   491→                    );
   492→                }
   493→            }
   494→        } else if (selection.label.startsWith('$(pencil)')) {
   495→            const phoneticHint = await vscode.window.showInputBox({
   496→                title: 'Edit Phonetic Hint',
   497→                placeHolder: 'Enter phonetic pronunciation',
   498→                value: '',
   499→                prompt: 'Enter how the word should be pronounced',
   500→            });
   501→
   502→            if (phoneticHint !== undefined) {
   503→                // Need to re-add the term with new phonetic hint
   504→                // (API doesn't have update endpoint, so we remove and re-add)
   505→                try {
   506→                    const client = await this.getClient();
   507→                    await client.removeVocabularyTerm(word);
   508→                    await client.addVocabularyTerm(word, 'general', phoneticHint || undefined);
   509→                    this.log(`Updated phonetic hint for: ${word}`);
   510→                    vscode.window.showInformationMessage(`Updated phonetic hint for "${word}"`);
   511→                } catch (error) {
   512→                    this.log(`Error updating phonetic hint: ${error}`);
   513→                    vscode.window.showErrorMessage(
   514→                        `Failed to update phonetic hint: ${error instanceof Error ? error.message : String(error)}`
   515→                    );
   516→                }
   517→            }
   518→        }
   519→    }
