   521→    /**
   522→     * Remove multiple vocabulary terms.
   523→     */
   524→    private async removeMultipleVocabularyTerms(vocabulary: VocabularyTerm[]): Promise<void> {
   525→        const items = vocabulary.map((term) => ({
   526→            label: term.word,
   527→            picked: false,
   528→        }));
   529→
   530→        const selected = await vscode.window.showQuickPick(items, {
   531→            title: 'Remove Vocabulary Terms',
   532→            placeHolder: 'Select terms to remove',
   533→            canPickMany: true,
   534→        });
   535→
   536→        if (!selected || selected.length === 0) {
   537→            return;
   538→        }
   539→
   540→        const confirmed = await vscode.window.showWarningMessage(
   541→            `Remove ${selected.length} vocabulary term(s)?`,
   542→            { modal: true },
   543→            'Remove',
   544→            'Cancel'
   545→        );
   546→
   547→        if (confirmed !== 'Remove') {
   548→            return;
   549→        }
   550→
   551→        try {
   552→            const client = await this.getClient();
   553→            let removed = 0;
   554→
   555→            for (const term of selected) {
   556→                try {
   557→                    await client.removeVocabularyTerm(term.label);
   558→                    removed++;
   559→                } catch (error) {
   560→                    this.log(`Error removing ${term.label}: ${error}`);
   561→                }
   562→            }
   563→
   564→            this.log(`Removed ${removed} vocabulary terms`);
   565→            vscode.window.showInformationMessage(`Removed ${removed} of ${selected.length} vocabulary terms`);
   566→        } catch (error) {
   567→            this.log(`Error removing vocabulary terms: ${error}`);
   568→            vscode.window.showErrorMessage(
   569→                `Failed to remove vocabulary terms: ${error instanceof Error ? error.message : String(error)}`
   570→            );
   571→        }
   572→    }
