    75→export class UserPreferencesClient {
    76→    private constructor(
    77→        private readonly apiUrl: string,
    78→        private readonly getAuthHeader: () => Promise<string | undefined>
    79→    ) {}
    80→
    81→    /**
    82→     * Create a UserPreferencesClient instance.
    83→     *
    84→     * @param apiUrl - Base API URL
    85→     * @param getAuthHeader - Function to get authorization header
    86→     * @returns UserPreferencesClient instance
    87→     */
    88→    public static create(
    89→        apiUrl: string,
    90→        getAuthHeader: () => Promise<string | undefined>
    91→    ): UserPreferencesClient {
    92→        return new UserPreferencesClient(apiUrl, getAuthHeader);
    93→    }
    94→
    95→    /**
    96→     * Make an authenticated API request.
    97→     */
    98→    private async request<T>(
    99→        path: string,
   100→        options: RequestInit = {}
   101→    ): Promise<T> {
   102→        const authHeader = await this.getAuthHeader();
   103→        if (!authHeader) {
   104→            throw new Error('Not authenticated');
   105→        }
   106→
   107→        const url = `${this.apiUrl}${path}`;
   108→        const response = await fetch(url, {
   109→            ...options,
   110→            headers: {
   111→                'Authorization': authHeader,
   112→                'Content-Type': 'application/json',
   113→                ...options.headers,
   114→            },
   115→        });
   116→
   117→        if (!response.ok) {
   118→            const error = await response.text().catch(() => 'Unknown error');
   119→            throw new Error(`API error (${response.status}): ${error}`);
   120→        }
   121→
   122→        return response.json() as Promise<T>;
   123→    }
