   342→        if (analysis.commands.length > 0) {
   343→            output += '\nCommands:\n';
   344→            for (const cmd of analysis.commands) {
   345→                output += `  • ${cmd.action}`;
   346→                if (cmd.isTerminal) output += ' (terminal)';
   347→                if (cmd.params) output += ` ${JSON.stringify(cmd.params)}`;
   348→                output += '\n';
   349→            }
   350→        }
   351→
   352→        this.outputChannel.clear();
   353→        this.outputChannel.append(output);
   354→        this.outputChannel.show();
   355→    }
   356→
   357→    /**
   358→     * List all available voice commands (ADR-008)
   359→     */
   360→    private async listVoiceCommands(): Promise<void> {
   361→        const parser = CommandParser.withSettings();
   362→        const commands = parser.getCommandList();
   363→
   364→        // Group commands by category
   365→        const categories = new Map<string, typeof commands>();
   366→        for (const cmd of commands) {
   367→            const category = this.categorizeCommand(cmd.action);
   368→            if (!categories.has(category)) {
   369→                categories.set(category, []);
   370→            }
   371→            categories.get(category)!.push(cmd);
   372→        }
   373→
   374→        // Build formatted message
   375→        let message = 'VTThought Voice Commands\n\n';
   376→        for (const [category, cmds] of categories.entries()) {
   377→            message += `## ${category}\n`;
   378→            for (const cmd of cmds) {
   379→                const triggers = cmd.trigger.join(', ');
   380→                message += `  • "${triggers}" → ${cmd.action}\n`;
   381→            }
   382→            message += '\n';
   383→        }
   384→
   385→        // Show in output channel
   386→        this.outputChannel.clear();
   387→        this.outputChannel.append(message);
   388→        this.outputChannel.show();
   389→
   390→        vscode.window.showInformationMessage(
   391→            'Voice commands listed in VTThought output channel'
   392→        );
   393→    }
   394→
   395→    private categorizeCommand(action: string): string {
   396→        if (action.startsWith('terminal.')) return 'Execution Commands';
   397→        if (action.startsWith('editor.action') || action === 'undo' || action === 'redo' || action === 'type') return 'Editing Commands';
   398→        if (action === 'workbench.action.gotoLine' || action === 'editorScroll' || action === 'cursorHome' || action === 'cursorEnd') return 'Navigation Commands';
   399→        if (action.startsWith('workbench.action') || action.startsWith('workbench.view')) return 'VS Code Commands';
   400→        if (action === 'vtthought.toggleRecording') return 'Dictation Control';
   401→        return 'Other';
   402→    }
   403→
   404→    /**
   405→     * Toggle recording state
   406→     */
   407→    private toggleRecording(): void {
   408→        if (!this.state.isConnected) {
   409→            vscode.window.showWarningMessage(
   410→                'VTThought is not connected to the backend. Connect first.'
   411→            );
   412→            return;
   413→        }
   414→
   415→        this.state.isRecording = !this.state.isRecording;
   416→        this.updateStatusDisplay();
   417→
   418→        if (this.state.isRecording) {
   419→            this.startRecording();
   420→        } else {
   421→            this.stopRecording();
   422→        }
   423→    }
