   425→    /**
   426→     * Start recording
   427→     */
   428→    private startRecording(): void {
   429→        this.log('Starting recording...');
   430→
   431→        // Send start signal to backend
   432→        if (this.audioStreamer?.isConnected) {
   433→            this.audioStreamer.startRecording();
   434→        }
   435→
   436→        // Start audio capture in WebView
   437→        this.voiceInputViewProvider.startRecording();
   438→
   439→        vscode.window.showInformationMessage('VTThought: Recording started');
   440→    }
   441→
   442→    /**
   443→     * Stop recording
   444→     */
   445→    private stopRecording(): void {
   446→        this.log('Stopping recording...');
   447→
   448→        // Stop audio capture in WebView
   449→        this.voiceInputViewProvider.stopRecording();
   450→
   451→        // Send stop signal to backend
   452→        if (this.audioStreamer?.isConnected) {
   453→            this.audioStreamer.stopRecording();
   454→        }
   455→
   456→        vscode.window.showInformationMessage('VTThought: Recording stopped');
   457→    }
