   473→    /**
   474→     * Setup authentication (ADR-002)
   475→     */
   476→    private async setupAuthentication(): Promise<void> {
   477→        this.log('Starting authentication setup...');
   478→
   479→        // Step 1: Get backend URL
   480→        const backendUrl = await vscode.window.showInputBox({
   481→            prompt: 'Enter your VTThought backend URL',
   482→            value: this.state.backendUrl,
   483→            placeHolder: 'http://localhost:8000',
   484→            validateInput: (value) => {
   485→                if (!value || !value.startsWith('http')) {
   486→                    return 'Please enter a valid URL (http:// or https://)';
   487→                }
   488→                return null;
   489→            }
   490→        });
   491→
   492→        if (!backendUrl) {
   493→            this.log('Authentication setup cancelled: No backend URL provided');
   494→            return;
   495→        }
   496→
   497→        // Normalize URL (remove trailing slash)
   498→        const normalizedUrl = backendUrl.replace(/\/$/, '');
   499→        await this.tokenManager.storeBackendUrl(normalizedUrl);
   500→        this.state.backendUrl = normalizedUrl;
   501→
   502→        // Step 2: Test backend connection
   503→        this.log(`Testing connection to ${normalizedUrl}...`);
   504→        try {
   505→            const response = await fetch(`${normalizedUrl}/api/auth/mode`);
   506→            if (!response.ok) {
   507→                throw new Error(`HTTP ${response.status}`);
   508→            }
   509→
   510→            const authMode = await response.json() as { mode: string; single_user_mode: boolean };
   511→            this.log(`Backend auth mode: ${authMode.mode}`);
   512→
   513→            if (authMode.single_user_mode) {
   514→                // Single-user mode: no token needed
   515→                vscode.window.showInformationMessage(
   516→                    'VTThought: Backend configured in single-user mode. No token required.'
   517→                );
   518→                this.state.isAuthenticated = true;
   519→                this.updateStatusDisplay();
   520→                return;
   521→            }
   522→        } catch (error) {
   523→            const message = error instanceof Error ? error.message : String(error);
   524→            vscode.window.showErrorMessage(
   525→                `VTThought: Failed to connect to backend at ${normalizedUrl}. ${message}`
   526→            );
   527→            this.log(`Backend connection failed: ${message}`);
   528→            return;
   529→        }
   530→
   531→        // Step 3: Get token from user
   532→        const token = await vscode.window.showInputBox({
   533→            prompt: 'Enter your VTThought extension token (from backend settings)',
   534→            password: true,
   535→            placeHolder: 'vct_...',
   536→            validateInput: (value) => {
   537→                if (!value || !value.startsWith('vct_')) {
   538→                    return 'Please enter a valid token (starts with vct_)';
   539→                }
   540→                return null;
   541→            }
   542→        });
   543→
   544→        if (!token) {
   545→            this.log('Authentication setup cancelled: No token provided');
   546→            return;
   547→        }
   548→
   549→        // Store token
   550→        await this.tokenManager.storeToken(token);
   551→        this.state.isAuthenticated = true;
   552→
   553→        this.log('Authentication configured successfully');
   554→        vscode.window.showInformationMessage(
   555→            'VTThought: Authentication configured successfully!'
   556→        );
   557→        this.updateStatusDisplay();
   558→    }
   559→
   560→    /**
   561→     * Clear authentication (ADR-002)
   562→     */
   563→    private async clearAuthentication(): Promise<void> {
   564→        const result = await vscode.window.showWarningMessage(
   565→            'Are you sure you want to clear your authentication settings?',
   566→            { modal: true },
   567→            'Clear',
   568→            'Cancel'
   569→        );
   570→
   571→        if (result === 'Clear') {
   572→            await this.tokenManager.clearAll();
   573→            this.state.isAuthenticated = false;
   574→            this.disconnect();
   575→            this.log('Authentication cleared');
   576→            vscode.window.showInformationMessage('VTThought: Authentication cleared');
   577→            this.updateStatusDisplay();
   578→        }
   579→    }
