   581→    /**
   582→     * Show authentication status (ADR-002)
   583→     */
   584→    private async showAuthenticationStatus(): Promise<void> {
   585→        const authStatus = await getAuthStatus(this.tokenManager);
   586→
   587→        const message = `
   588→VTThought Authentication Status
   589→===============================
   590→Authenticated: ${authStatus.isConfigured ? 'Yes' : 'No'}
   591→Backend URL: ${authStatus.backendUrl}
   592→`.trim();
   593→
   594→        this.log(message);
   595→        vscode.window.showInformationMessage(message);
   596→    }
   597→
   598→    /**
   599→     * Run the first-run setup flow (ADR-017)
   600→     */
   601→    private async runSetup(): Promise<void> {
   602→        this.log('Starting setup flow...');
   603→        const setupFlow = new SetupFlow(this.context, this.tokenManager);
   604→        await setupFlow.start();
   605→    }
   606→
   607→    /**
   608→     * Reset the first-run setup (ADR-017)
   609→     */
   610→    private async resetSetup(): Promise<void> {
   611→        const result = await vscode.window.showWarningMessage(
   612→            'This will reset VTThought to first-run state. You will need to set up authentication again.',
   613→            { modal: true },
   614→            'Reset',
   615→            'Cancel'
   616→        );
   617→
   618→        if (result === 'Reset') {
   619→            await SetupFlow.reset(this.context);
   620→            await this.tokenManager.clearAll();
   621→            this.state.isAuthenticated = false;
   622→            this.disconnect();
   623→            this.log('Setup reset');
   624→            vscode.window.showInformationMessage(
   625→                'VTThought has been reset. Click the status bar or run "VTThought: Run Setup" to start again.'
   626→            );
   627→            this.updateStatusDisplay();
   628→        }
   629→    }
   630→
   631→    /**
   632→     * Connect to backend WebSocket
   633→     */
   634→    private async connectBackend(): Promise<void> {
   635→        // Check authentication first (ADR-002)
   636→        if (!this.state.isAuthenticated) {
   637→            const result = await vscode.window.showWarningMessage(
   638→                'VTThought is not configured. Would you like to set up authentication?',
   639→                'Setup',
   640→                'Cancel'
   641→            );
   642→
   643→            if (result === 'Setup') {
   644→                await this.setupAuthentication();
   645→                if (!this.state.isAuthenticated) {
   646→                    this.log('Connection cancelled: Authentication not configured');
   647→                    return;
   648→                }
   649→            } else {
   650→                this.log('Connection cancelled: Authentication not configured');
   651→                return;
   652→            }
   653→        }
   654→
   655→        const apiUrl = await this.tokenManager.getBackendUrl();
   656→        const wsUrl = await this.tokenManager.getWebSocketUrl();
   657→
   658→        this.log(`Connecting to backend: ${apiUrl}`);
   659→
   660→        try {
   661→            // First, verify backend is reachable via health check
   662→            const authHeader = await this.tokenManager.getAuthHeader();
   663→            const headers: Record<string, string> = {};
   664→            if (authHeader) {
   665→                headers['Authorization'] = authHeader;
   666→            }
   667→
   668→            const response = await fetch(`${apiUrl}/api/health`, { headers });
   669→
   670→            if (!response.ok) {
   671→                if (response.status === 401) {
   672→                    // Token expired or invalid
   673→                    await this.tokenManager.clearToken();
   674→                    this.state.isAuthenticated = false;
   675→                    vscode.window.showErrorMessage(
   676→                        'VTThought: Authentication failed. Please set up authentication again.',
   677→                        'Setup'
   678→                    ).then(action => {
   679→                        if (action === 'Setup') {
   680→                            vscode.commands.executeCommand('vtthought.setupAuthentication');
   681→                        }
   682→                    });
   683→                    return;
   684→                }
   685→                throw new Error(`Health check failed: ${response.status}`);
   686→            }
   687→
   688→            // Establish WebSocket connection
   689→            this.audioStreamer = new AudioStreamer(wsUrl, { sampleRate: 16000, channels: 1 }, {
   690→                onConnected: () => {
   691→                    this.state.isConnected = true;
   692→                    this.updateStatusDisplay();
   693→                    this.log('WebSocket connected successfully');
   694→                },
   695→                onDisconnected: () => {
   696→                    this.state.isConnected = false;
   697→                    this.state.isRecording = false;
   698→                    this.updateStatusDisplay();
   699→                    this.log('WebSocket disconnected');
   700→                },
   701→                onError: (error) => {
   702→                    this.log(`WebSocket error: ${error.message}`);
   703→                    vscode.window.showErrorMessage(`VTThought: WebSocket error - ${error.message}`);
   704→                },
   705→                onMessage: async (message) => {
   706→                    // Handle server messages (interim, streaming, final, error)
   707→                    if (this.dictationHandler) {
   708→                        await this.dictationHandler.handleMessage(message);
   709→                    }
   710→                }
   711→            });
   712→
   713→            await this.audioStreamer.connect();
   714→
   715→            this.log('Connected to backend successfully');
   716→            vscode.window.showInformationMessage('VTThought: Connected to backend');
   717→
   718→        } catch (error) {
   719→            this.log(`Connection failed: ${error}`);
   720→            vscode.window.showErrorMessage(
   721→                `VTThought: Failed to connect to backend at ${apiUrl}. Ensure the backend is running and try again.`
   722→            );
   723→            this.state.isConnected = false;
   724→            this.updateStatusDisplay();
   725→        }
   726→    }
