   389→### Activation Mode Registry
   390→
   391→```typescript
   392→/**
   393→ * Registry for all available activation modes.
   394→ * Allows dynamic mode switching and future mode additions.
   395→ */
   396→class ActivationModeRegistry {
   397→    private modes = new Map<string, ActivationMode>();
   398→    private activeMode: ActivationMode | null = null;
   399→    private callbacks: ActivationCallbacks | null = null;
   400→
   401→    constructor() {
   402→        // Register built-in modes
   403→        this.register(new PushToTalkMode());
   404→        this.register(new ToggleMode());
   405→        this.register(new VADMode());
   406→    }
   407→
   408→    /**
   409→     * Register a new activation mode.
   410→     */
   411→    register(mode: ActivationMode): void {
   412→        this.modes.set(mode.id, mode);
   413→    }
   414→
   415→    /**
   416→     * Get all available modes.
   417→     */
   418→    getAvailableModes(): { id: string; displayName: string }[] {
   419→        return Array.from(this.modes.values()).map(m => ({
   420→            id: m.id,
   421→            displayName: m.displayName
   422→        }));
   423→    }
   424→
   425→    /**
   426→     * Set the callbacks for activation events.
   427→     */
   428→    setCallbacks(callbacks: ActivationCallbacks): void {
   429→        this.callbacks = callbacks;
   430→    }
   431→
   432→    /**
   433→     * Switch to a different activation mode.
   434→     */
   435→    switchMode(modeId: string): void {
   436→        const newMode = this.modes.get(modeId);
   437→        if (!newMode) {
   438→            throw new Error(`Unknown activation mode: ${modeId}`);
   439→        }
   440→
   441→        // Disable current mode
   442→        if (this.activeMode) {
   443→            this.activeMode.disable();
   444→            this.activeMode.dispose();
   445→        }
   446→
   447→        // Enable new mode
   448→        this.activeMode = newMode;
   449→        if (this.callbacks) {
   450→            this.activeMode.initialize(this.callbacks);
   451→        }
   452→        this.activeMode.enable();
   453→    }
   454→
   455→    /**
   456→     * Get current mode state.
   457→     */
   458→    getState(): ActivationState | null {
   459→        return this.activeMode?.state ?? null;
   460→    }
   461→
   462→    /**
   463→     * Dispose all resources.
   464→     */
   465→    dispose(): void {
   466→        if (this.activeMode) {
   467→            this.activeMode.disable();
   468→            this.activeMode.dispose();
   469→        }
   470→    }
   471→}
