   209→            input: testCase.input,
   210→            expectedText: testCase.expectedText,
   211→            actualText: result.text,
   212→            expectedCommands: testCase.expectedCommands,
   213→            actualCommands: result.commands.length,
   214→            expectedActions: testCase.expectedActions,
   215→            actualActions: result.commands.map(c => c.action),
   216→            details: passed ? undefined : {
   217→                textMatch,
   218→                commandCountMatch,
   219→                actionMatch
   220→            }
   221→        };
