   316→    /**
   317→     * Analyze a transcription for voice commands
   318→     */
   319→    private async analyzeVoiceCommand(): Promise<void> {
   320→        const input = await vscode.window.showInputBox({
   321→            prompt: 'Enter text to analyze for voice commands',
   322→            placeHolder: 'create a function called hello enter'
   323→        });
   324→
   325→        if (!input) {
   326→            return;
   327→        }
   328→
   329→        const parser = CommandParser.withSettings();
   330→        const tester = createCommandTester(parser);
   331→        const analysis = tester.analyze(input);
   332→
   333→        // First apply homophone normalization
   334→        const normalized = normalizeCommand(input);
   335→
   336→        let output = `Voice Command Analysis\n\n`;
   337→        output += `Original: "${input}"\n`;
   338→        output += `Normalized: "${normalized}"\n`;
   339→        output += `Cleaned text: "${analysis.cleaned}"\n`;
   340→        output += `Commands found: ${analysis.commandsFound}\n`;
   341→
   342→        if (analysis.commands.length > 0) {
   343→            output += '\nCommands:\n';
   344→            for (const cmd of analysis.commands) {
   345→                output += `  • ${cmd.action}`;
   346→                if (cmd.isTerminal) output += ' (terminal)';
   347→                if (cmd.params) output += ` ${JSON.stringify(cmd.params)}`;
   348→                output += '\n';
   349→            }
   350→        }
   351→
   352→        this.outputChannel.clear();
   353→        this.outputChannel.append(output);
   354→        this.outputChannel.show();
   355→    }
