   357→    /**
   358→     * List all available voice commands (ADR-008)
   359→     */
   360→    private async listVoiceCommands(): Promise<void> {
   361→        const parser = CommandParser.withSettings();
   362→        const commands = parser.getCommandList();
   363→
   364→        // Group commands by category
   365→        const categories = new Map<string, typeof commands>();
   366→        for (const cmd of commands) {
   367→            const category = this.categorizeCommand(cmd.action);
   368→            if (!categories.has(category)) {
   369→                categories.set(category, []);
   370→            }
   371→            categories.get(category)!.push(cmd);
   372→        }
   373→
   374→        // Build formatted message
   375→        let message = 'VTThought Voice Commands\n\n';
   376→        for (const [category, cmds] of categories.entries()) {
   377→            message += `## ${category}\n`;
   378→            for (const cmd of cmds) {
   379→                const triggers = cmd.trigger.join(', ');
   380→                message += `  • "${triggers}" → ${cmd.action}\n`;
   381→            }
   382→            message += '\n';
   383→        }
   384→
   385→        // Show in output channel
   386→        this.outputChannel.clear();
   387→        this.outputChannel.append(message);
   388→        this.outputChannel.show();
   389→
   390→        vscode.window.showInformationMessage(
   391→            'Voice commands listed in VTThought output channel'
   392→        );
   393→    }
