   395→    private categorizeCommand(action: string): string {
   396→        if (action.startsWith('terminal.')) return 'Execution Commands';
   397→        if (action.startsWith('editor.action') || action === 'undo' || action === 'redo' || action === 'type') return 'Editing Commands';
   398→        if (action === 'workbench.action.gotoLine' || action === 'editorScroll' || action === 'cursorHome' || action === 'cursorEnd') return 'Navigation Commands';
   399→        if (action.startsWith('workbench.action') || action.startsWith('workbench.view')) return 'VS Code Commands';
   400→        if (action === 'vtthought.toggleRecording') return 'Dictation Control';
   401→        return 'Other';
   402→    }
