     4→ * Utilities for testing voice command parsing and execution.
     5→ */
     6→
     7→import { CommandParser, ParsedTranscription, VoiceCommand, normalizeCommand } from './voiceCommands';
     8→
     9→/**
    10→ * Test case for voice command parsing
    11→ */
