    19→
    20→/**
    21→ * Run voice command parser tests
    22→ */
    23→export function runCommandParserTests(parser: CommandParser): TestResult[] {
    24→    const results: TestResult[] = [];
    25→
    26→    const testCases: CommandTestCase[] = [
    27→        // Execution Commands
    28→        {
