   194→        const commandCountMatch = result.commands.length === testCase.expectedCommands;
   195→
   196→        let actionMatch = true;
   197→        if (testCase.expectedActions && testCase.expectedActions.length > 0) {
   198→            const actualActions = result.commands.map(c => c.action);
   199→            actionMatch = testCase.expectedActions.every(expected =>
   200→                actualActions.includes(expected)
   201→            );
   202→        }
   203→
   204→        const passed = textMatch && commandCountMatch && actionMatch;
   205→
   206→        return {
   207→            description: testCase.description,
   208→            passed,
   209→            input: testCase.input,
   210→            expectedText: testCase.expectedText,
   211→            actualText: result.text,
   212→            expectedCommands: testCase.expectedCommands,
   213→            actualCommands: result.commands.length,
   214→            expectedActions: testCase.expectedActions,
   215→            actualActions: result.commands.map(c => c.action),
   216→            details: passed ? undefined : {
   217→                textMatch,
   218→                commandCountMatch,
   219→                actionMatch
   220→            }
   221→        };
   222→    } catch (error) {
   223→        return {
   224→            description: testCase.description,
   225→            passed: false,
   226→            input: testCase.input,
   227→            expectedText: testCase.expectedText,
   228→            actualText: '',
   229→            expectedCommands: testCase.expectedCommands,
   230→            actualCommands: 0,
   231→            error: error instanceof Error ? error.message : String(error)
   232→        };
   233→    }
   234→}
   235→
   236→/**
   237→ * Test result
   238→ */
   239→export interface TestResult {
   240→    description: string;
   241→    passed: boolean;
   242→    input: string;
   243→    expectedText: string;
   244→    actualText: string;
   245→    expectedCommands: number;
   246→    actualCommands: number;
   247→    expectedActions?: string[];
   248→    actualActions?: string[];
   249→    details?: {
   250→        textMatch: boolean;
   251→        commandCountMatch: boolean;
   252→        actionMatch: boolean;
   253→    };
   254→    error?: string;
   255→}
   256→
   257→/**
   258→ * Format test results for display
   259→ */
   260→export function formatTestResults(results: TestResult[]): string {
   261→    const passed = results.filter(r => r.passed).length;
   262→    const total = results.length;
   263→
   264→    let output = `Voice Command Test Results: ${passed}/${total} passed\n\n`;
   265→
   266→    for (const result of results) {
   267→        const status = result.passed ? '✓' : '✗';
   268→        output += `${status} ${result.description}\n`;
   269→
   270→        if (!result.passed) {
   271→            output += `  Input: "${result.input}"\n`;
   272→            output += `  Expected text: "${result.expectedText}"\n`;
   273→            output += `  Actual text: "${result.actualText}"\n`;
   274→            output += `  Expected commands: ${result.expectedCommands}\n`;
   275→            output += `  Actual commands: ${result.actualCommands}\n`;
   276→
   277→            if (result.expectedActions) {
   278→                output += `  Expected actions: ${result.expectedActions.join(', ')}\n`;
   279→            }
   280→            if (result.actualActions && result.actualActions.length > 0) {
   281→                output += `  Actual actions: ${result.actualActions.join(', ')}\n`;
   282→            }
   283→
   284→            if (result.details) {
   285→                output += `  Details: text=${result.details.textMatch ? '✓' : '✗'}, `;
   286→                output += `count=${result.details.commandCountMatch ? '✓' : '✗'}, `;
   287→                output += `action=${result.details.actionMatch ? '✓' : '✗'}\n`;
   288→            }
   289→
   290→            if (result.error) {
   291→                output += `  Error: ${result.error}\n`;
   292→            }
   293→
   294→            output += '\n';
   295→        }
   296→    }
   297→
   298→    return output;
   299→}
   300→
   301→/**
   302→ * Interactive command testing utility
   303→ * Returns a function that can be used to test commands
   304→ */
   305→export function createCommandTester(parser: CommandParser) {
   306→    return {
   307→        /**
   308→         * Test a single transcription
   309→         */
   310→        test(transcription: string): ParsedTranscription {
   311→            return parser.parse(transcription);
   312→        },
   313→
   314→        /**
   315→         * Show command breakdown for a transcription
   316→         */
   317→        analyze(transcription: string): CommandAnalysis {
   318→            const result = parser.parse(transcription);
   319→
   320→            return {
   321→                original: transcription,
   322→                cleaned: result.text,
   323→                commandsFound: result.commands.length,
   324→                commands: result.commands.map(cmd => ({
   325→                    action: cmd.action,
   326→                    params: cmd.params,
   327→                    isTerminal: cmd.terminal || false
   328→                })),
   329→                hasTrailingCommand: result.hasTrailingCommand
   330→            };
   331→        },
   332→
   333→        /**
   334→         * Get all available command triggers
   335→         */
   336→        getAllTriggers(): string[] {
   337→            const commands = parser.getCommandList();
   338→            const triggers = new Set<string>();
   339→            for (const cmd of commands) {
   340→                for (const trigger of cmd.trigger) {
   341→                    triggers.add(trigger);
   342→                }
   343→            }
   344→            return Array.from(triggers).sort();
   345→        }
   346→    };
   347→}
   348→
   349→/**
   350→ * Command analysis result
   351→ */
   352→export interface CommandAnalysis {
   353→    original: string;
   354→    cleaned: string;
   355→    commandsFound: number;
   356→    commands: Array<{
   357→        action: string;
   358→        params?: Record<string, unknown>;
   359→        isTerminal: boolean;
   360→    }>;
   361→    hasTrailingCommand: boolean;
   362→}
   363→
   364→/**
   365→ * Test homophone normalization
   366→ */
   367→export function testHomophoneNormalization(normalizeFn: (text: string) => string): HomophoneTestResult[] {
   368→    const tests: Array<{ input: string; expected: string; description: string }> = [
   369→        { input: 'inter that', expected: 'enter that', description: 'inter -> enter' },
   370→        { input: 'un do that', expected: 'undo that', description: 'un do -> undo' },
   371→        { input: 'copy that line', expected: 'copy that line', description: 'copy unchanged' },
   372→        { input: 'select the word', expected: 'select word', description: 'select the -> select' },
   373→        { input: 'skroll up', expected: 'scroll up', description: 'skroll -> scroll' },
   374→    ];
   375→
   376→    return tests.map(test => {
   377→        const result = normalizeFn(test.input);
   378→        return {
   379→            description: test.description,
   380→            input: test.input,
   381→            expected: test.expected,
   382→            actual: result,
   383→            passed: result === test.expected
   384→        };
   385→    });
   386→}
   387→
   388→/**
   389→ * Homophone test result
   390→ */
   391→export interface HomophoneTestResult {
   392→    description: string;
   393→    input: string;
   394→    expected: string;
   395→    actual: string;
   396→    passed: boolean;
   397→}
